    """Tuned Best Fit (lo=7, hi=27, penalty=75): the tightest bin wins, but leaving a gap
    strictly between 7 and 27 units costs 75. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 75 * ((r > 7) & (r < 27))

