    """Tuned Best Fit (lo=4, hi=37, penalty=5): the tightest bin wins, but leaving a gap
    strictly between 4 and 37 units costs 5. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 5 * ((r > 4) & (r < 37))

